import {uid,today,addDays,dayDiff,prettyDate,validateGoal,suggestCheckpoints,generatePlan,periods,currentPeriod,streak,createDemo,validateImport,isDate} from './planner.js';
import {createWorkspaceSync} from './sync.js';

const accountElement=document.getElementById('reflect-account');
let account=null;
try{const parsed=accountElement?JSON.parse(accountElement.textContent):null;if(parsed&&typeof parsed.id==='string'&&typeof parsed.email==='string')account=parsed;}catch{}
const KEY=account?`reflect-ai-v1:${account.id}`:'reflect-ai-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={
  logo:'<path d="M5 20V4h7c6 0 7 9 0 9H5m7 0 7 7M18 2v5m-2-3h5"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',
  plan:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h1m4 0h3M8 12h1m4 0h3M8 16h1m4 0h3"/>',
  reflect:'<path d="M12 6v15M3 4c3-1 6 0 9 2 3-2 6-3 9-2v15c-3-1-6 0-9 2-3-2-6-3-9-2V4Z"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  back:'<path d="M19 12H5m5-5-5 5 5 5"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18M8 14h1m6 0h1m-8 3h1"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  flame:'<path d="M12 3c1 5 5 6 5 10 3-1 3-3 3-3 2 7-2 12-8 12S3 17 4 13c1-4 4-6 8-10Z"/><path d="M12 13c0 2-3 3-3 5a3 3 0 0 0 6 0c0-2-2-3-3-5Z"/>',
  leaf:'<path d="M20 3c-9-1-16 3-16 10 0 5 5 8 10 5 4-2 6-8 6-15ZM4 21 16 8"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15l-1 5Z"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/>',
  upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v4h16v-4"/>',
  heart:'<path d="M12 20 4 12a5 5 0 0 1 8-6 5 5 0 0 1 8 6l-8 8Z"/>',
  spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3ZM20 2v4m-2-2h4"/>',
  flag:'<path d="M5 22V3c5-3 9 3 14 0v11c-5 3-9-3-14 0"/>',
  archive:'<path d="M4 8v12h16V8M3 3h18v5H3V3Zm6 10h6"/>',
  pause:'<path d="M8 5v14m8-14v14"/>',
  play:'<path d="m8 4 12 8-12 8V4Z"/>',
  undo:'<path d="M5 9h9a6 6 0 0 1 0 12M5 9l5-5M5 9l5 5"/>',
  trash:'<path d="M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>'
};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.spark}</svg>`;
let state,storageError=false,view='today',draft=null,wizardStep=1,preview=null,dialogType=null,lastFocus=null;
let timer={remaining:25*60,until:null,running:false};
let toastTimeout;
let cloud=null,sync=null,cloudStatus='saved',recovered=null,resumePending=false;
const SYNC_KEY=KEY+':sync',RECOVERY_KEY=KEY+':recovered';
try{const value=JSON.parse(document.getElementById('reflect-workspace')?.textContent||'null');if(account&&value&&Number.isSafeInteger(value.revision)&&value.revision>=0&&(value.state===null||validateImport(value.state)))cloud=value;}catch{}
try {
 let raw=localStorage.getItem(KEY);
 if(!raw&&account?.legacyOwner){const legacy=localStorage.getItem('reflect-ai-v1');if(legacy&&validateImport(JSON.parse(legacy))){raw=legacy;localStorage.setItem(KEY,legacy);}}
 const saved=raw?JSON.parse(raw):null;
 state=cloud?.state||(validateImport(saved)?saved:createDemo());
 if(raw&&!validateImport(saved))storageError=true;
 if(cloud){
  const pending=JSON.parse(localStorage.getItem(SYNC_KEY)||'null');
  if(pending&&validateImport(pending.state)){
   if(pending.revision===cloud.revision){state=pending.state;resumePending=true;}
   else{localStorage.setItem(RECOVERY_KEY,JSON.stringify(pending.state));localStorage.removeItem(SYNC_KEY);}
  }else if(!cloud.state&&validateImport(saved)){state=saved;resumePending=true;}
  const backup=JSON.parse(localStorage.getItem(RECOVERY_KEY)||'null');if(validateImport(backup))recovered=backup;
 }
}catch{state=cloud?.state||createDemo();storageError=true;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;return true;}catch{storageError=true;return false;}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function saved(message){const ok=persist();if(sync)sync.enqueue(state);render();notify(ok?message+(sync?' Saving to your account…':''):'Your change is in this session. Browser storage is unavailable; export a backup.');}
function syncNotice(){
 if(!sync)return '';
 const notices={offline:'Cloud save is unavailable. Your changes are kept in this browser. Retry when you are online.',conflict:'Another device changed this workspace. Export your current workspace from Settings, then reload to load the saved version.', 'signed-out':'Your session has expired. Export a backup from Settings, then sign in again.'};
 return notices[cloudStatus]?`<div class="storage-error" role="alert">${notices[cloudStatus]} ${cloudStatus==='offline'?'<button class="text-button" data-action="sync-retry">Retry save</button>':''}</div>`:recovered?'<div class="warning">An earlier unsaved version is preserved. Download it from Settings before restoring any changes.</div>':'';
}
if(cloud){
 sync=createWorkspaceSync({revision:cloud.revision,save:async(snapshot,revision)=>{
  const response=await fetch('/api/workspace',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:snapshot,revision})});
  if(!response.ok){const error=new Error('Cloud save failed');error.status=response.status;throw error;}return response.json();
 },onStatus:(status,revision,pending)=>{
  cloudStatus=status;
  try{if(pending)localStorage.setItem(SYNC_KEY,JSON.stringify({revision,state:pending}));else localStorage.removeItem(SYNC_KEY);}catch{storageError=true;}
  render();
 }});
 window.addEventListener('online',()=>sync.retry());
}
const done=()=>state.tasks.filter(t=>t.done).length;
const progress=()=>state.tasks.length?Math.round(done()/state.tasks.length*100):0;
const milestoneFor=id=>state.milestones.find(m=>m.id===id);
const typeName=t=>({weekly:'Weekly',monthly:'Monthly',end:'End-of-goal'}[t]);
const shortToday=()=>new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});

function art(){return `<svg class="hero-art" aria-hidden="true" viewBox="0 0 280 220" fill="none"><circle cx="193" cy="52" r="32" fill="#d7dfc8"/><circle cx="193" cy="52" r="22" fill="#e3e9d7"/><path d="M34 197h53v-41h52v-41h52V74h55v123H34Z" fill="#d6dec6"/><path d="M33 196h55v-40h51v-41h53V74h54" stroke="#9bad84" stroke-width="1.3"/><path d="M50 218c11-50 1-64-13-70m12 52c-17-3-26-20-23-32 18 4 30 17 23 32Zm1-20c13-10 14-25 8-32-12 7-17 19-8 32Z" stroke="#97a97c" stroke-width="1.2"/><path d="M231 215c-5-33 3-47 15-57m-12 37c14-3 20-15 18-24-13 4-20 14-18 24Zm-1-7c-11-6-14-19-10-26 12 6 17 15 10 26Z" stroke="#9bae83" stroke-width="1.2"/><path d="M119 125c0-5 4-9 9-9m25-64c-4-3-9-3-12 1m2 1c4-4 9-4 13-1M202 102c9 1 18-1 27-5" stroke="#afbd98" stroke-width="1.3"/><path d="M172 90c1-3 2-6 5-7m-3 3 6 1" stroke="#82996a" stroke-width="1.3"/><circle cx="153" cy="101" r="4" fill="#889c6e"/><path d="m151 107-8 14 11 7 6 17m-7-31 12 5m-13 10-6 15" stroke="#889c6e" stroke-width="2.5" stroke-linecap="round"/><path d="M97 43v7m-3-3h6M238 45v5m-2-2h4" stroke="#a6b68f"/></svg>`;}
function taskRow(t,showDate=false){const m=milestoneFor(t.milestoneId);return `<div class="task-row ${t.done?'task-complete':''}" data-task="${esc(t.id)}"><button class="task-check ${t.done?'checked':''}" data-action="toggle" data-id="${esc(t.id)}" aria-label="${t.done?'Mark incomplete':'Complete action'}: ${esc(t.title)}" aria-pressed="${t.done}">${t.done?icon('check'):''}</button><div class="task-info"><p class="task-title">${esc(t.title)}</p><div class="task-sub"><span>${icon('clock')}${t.minutes} min</span>${showDate?`<span class="${t.date<today()&&!t.done?'overdue':''}">${icon('calendar')}${prettyDate(t.date)}${t.date<today()&&!t.done?' · overdue':''}</span>`:t.date<today()&&!t.done?`<span class="overdue">From ${prettyDate(t.date)}</span>`:''}<span class="tag">${esc(m?.title||'My goal')}</span></div></div><div class="task-actions"><button class="icon-button" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Edit action: ${esc(t.title)}" title="Edit action">${icon('edit')}</button>${!t.done?`<button class="icon-button" data-action="reschedule" data-id="${esc(t.id)}" aria-label="Reschedule action: ${esc(t.title)}" title="Reschedule">${icon('calendar')}</button>`:''}</div></div>`;}
function nextCheckin(){const list=periods(state.goal,'weekly');return list.find(p=>!state.reflections.some(r=>r.periodKey===p.key))||list.at(-1);}
function todayView(){const now=today(),g=state.goal;const visible=state.tasks.filter(t=>t.date===now||(!t.done&&t.date<now)).sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));const completeToday=visible.filter(t=>t.done).length;const future=state.tasks.filter(t=>!t.done&&t.date>now).sort((a,b)=>a.date.localeCompare(b.date))[0];const p=nextCheckin();const checkinDone=state.reflections.some(r=>r.periodKey===p.key);const minutes=visible.filter(t=>!t.done).reduce((n,t)=>n+t.minutes,0);return `<div class="page-heading"><div><p class="eyebrow">A little intention goes a long way</p><h1>Small steps. Real progress.</h1></div><div class="date-pill">${icon('calendar')}${shortToday()}</div></div>${demoBanner()}<section class="goal-hero"><div class="goal-hero-copy"><p class="eyebrow">${state.mode==='demo'?'An example to make it yours':'Your active goal'}</p><h2>${esc(g.title)}</h2><div class="goal-meta"><span>${icon('calendar')}${prettyDate(g.startDate)} – ${prettyDate(g.endDate,{month:'short',day:'numeric',year:'numeric'})}</span><span>${icon('clock')}${g.dailyMinutes} min / workday</span></div><button class="button" data-action="nav" data-view="plan">See my plan ${icon('arrow')}</button></div>${art()}</section><section class="stats" aria-label="Goal progress"><div class="stat"><div class="stat-icon">${icon('target')}</div><div><strong>${progress()}<span style="font-size:14px">%</span></strong><small>Goal progress</small></div><span class="stat-extra">${done()} of ${state.tasks.length}</span></div><div class="stat"><div class="stat-icon">${icon('calendar')}</div><div><strong>${Math.max(0,dayDiff(now,g.endDate))}</strong><small>${now>g.endDate?'Deadline passed':'Days to go'}</small></div><span class="stat-extra">${prettyDate(g.endDate)}</span></div><div class="stat"><div class="stat-icon">${icon('flame')}</div><div><strong>${streak(state.tasks)}</strong><small>Day streak</small></div><span class="stat-extra">Keep showing up</span></div></section><div class="content-grid"><section class="card"><div class="section-header"><h2>Today, one step at a time</h2><small>${completeToday} / ${visible.length} done</small></div>${minutes>g.dailyMinutes?`<div class="warning">${minutes} minutes of open work, with a ${g.dailyMinutes}-minute daily budget. Move an action to another day to make this realistic.</div>`:''}<div class="task-list">${visible.length?visible.map(t=>taskRow(t)).join(''):`<div class="empty"><div class="empty-icon">${icon('sun')}</div><h3>${done()===state.tasks.length&&state.tasks.length?'You made it to the finish.':now<g.startDate?'Your next chapter is ready.':'A little breathing room.'}</h3><p>${done()===state.tasks.length&&state.tasks.length?'Take a moment to record what this goal taught you.':future?`Your next action is on ${prettyDate(future.date)}: ${esc(future.title)}.`:'There are no actions due today. Add a small next step or reflect on your progress.'}</p>${done()===state.tasks.length&&state.tasks.length?`<button class="button soft" data-action="reflection" data-type="end">Reflect on my goal</button>`:future?`<button class="button soft" data-action="edit-task" data-id="${esc(future.id)}">Review next action</button>`:''}</div>`}</div>${visible.length?`<div class="small-progress"><span style="width:${visible.length?completeToday/visible.length*100:0}%"></span></div>`:''}<div class="today-footer"><button class="text-button" data-action="add-task">${icon('plus')} Add an action</button><p>${minutes?`${minutes} minutes left today`:'Every step counts.'}</p></div><div class="focus-bar"><strong id="timer-display">${timerText()}</strong><span id="timer-caption">A little space to focus</span><button class="button soft" data-action="timer" id="timer-button">${icon(timer.running?'pause':'play')}${timer.running?'Pause':'Start focus'}</button><button class="icon-button" data-action="timer-reset" aria-label="Reset focus timer" title="Reset timer">${icon('undo')}</button></div><p class="timer-notice">25-minute focus timer. Take a break when you need one.</p></section><aside class="right-column"><div class="motivation-card"><p class="eyebrow">A thought for your journey</p><blockquote>${done()>0?'You’re building evidence that you can follow through. One step at a time.':'You don’t need a perfect day. Just one meaningful step.'}</blockquote><p>${done()>0?`${done()} small ${done()===1?'step':'steps'} completed. That is real progress.`:'Start where you are. Work with what you have.'}</p></div><div class="checkin-card"><p class="eyebrow">Pause. Notice. Keep growing.</p><h3>${checkinDone?'A moment to look back':'Your next weekly reflection'}</h3><p>${p.due?'Ready when you are':`Check in on ${prettyDate(p.end)}`}</p><button class="text-button" data-action="reflection" data-type="weekly" data-period="${esc(p.key)}">${checkinDone?'Revisit reflection':p.due?'Write reflection':'Write an early reflection'} ${icon('arrow')}</button></div><div class="why-card"><h3>${icon('heart')} Remember your why</h3><p>${esc(g.why||'Small, steady progress toward something that matters to you.')}</p></div></aside></div>`;}
function demoBanner(){return state.mode==='demo'?`<div class="demo-banner"><span>${icon('spark')}You’re exploring an example goal. Your own goal starts here.</span><button class="text-button" data-action="new-goal">Create your goal ${icon('arrow')}</button></div>`:'';}
function planView(){const g=state.goal;const dateTotals=new Map();for(const t of state.tasks.filter(t=>!t.done))dateTotals.set(t.date,(dateTotals.get(t.date)||0)+t.minutes);const overloaded=[...dateTotals].filter(([,m])=>m>g.dailyMinutes);return `<div class="page-heading"><div><p class="eyebrow">The path is made of small steps</p><h1>Your plan, at your pace.</h1><p class="subtext">A practical outline you can adjust as life happens.</p></div><button class="button secondary" data-action="new-goal">${icon('plus')} ${state.mode==='demo'?'Create goal':'Next goal'}</button></div>${demoBanner()}<section class="plan-summary"><div><p class="eyebrow">What you’re working toward</p><h2>${esc(g.title)}</h2><p>${esc(g.success)}</p><p style="margin-top:9px">${prettyDate(g.startDate)} – ${prettyDate(g.endDate)} · ${g.dailyMinutes} minutes per workday</p></div><div class="progress-info"><strong>${progress()}%</strong><p>${done()} of ${state.tasks.length} actions</p><div class="small-progress"><span style="width:${progress()}%"></span></div></div></section>${overloaded.length?`<div class="warning">${overloaded.length} ${overloaded.length===1?'day has':'days have'} more planned work than your ${g.dailyMinutes}-minute budget. Edit action dates or durations to lighten those days.</div>`:''}<div class="plan-toolbar"><p>${state.milestones.length} checkpoints · ${state.tasks.length} actions · ${state.tasks.reduce((n,t)=>n+t.minutes,0)} planned minutes</p><button class="text-button" data-action="add-task">${icon('plus')} Add action</button></div><section aria-label="Goal checkpoints">${state.milestones.map((m,i)=>{const tasks=state.tasks.filter(t=>t.milestoneId===m.id).sort((a,b)=>a.date.localeCompare(b.date));const all=tasks.length&&tasks.every(t=>t.done);return `<div class="milestone"><div class="milestone-header"><div class="milestone-number">${all?icon('check'):String(i+1).padStart(2,'0')}</div><div class="milestone-heading"><h3>${esc(m.title)}</h3><p>${esc(m.deliverable)}</p></div><span class="milestone-date">By ${prettyDate(m.date)}</span><button class="icon-button" data-action="edit-milestone" data-id="${esc(m.id)}" aria-label="Edit checkpoint: ${esc(m.title)}">${icon('edit')}</button></div><div class="task-list">${tasks.map(t=>taskRow(t,true)).join('')||'<p class="subtext">Add an action to this checkpoint.</p>'}</div></div>`;}).join('')}</section>`;}
function reflectionsView(){return `<div class="page-heading"><div><p class="eyebrow">A little perspective changes the next step</p><h1>Look back. Move forward.</h1><p class="subtext">A quiet place to notice what’s working and what needs to change.</p></div></div>${demoBanner()}<section class="reflection-intro">${icon('reflect')}<div><h2>Progress is something you learn from.</h2><p>Your reflections belong to this goal. Capture the lesson, then turn it into your next action.</p></div></section><section class="reflection-grid" aria-label="Reflection types">${['weekly','monthly','end'].map(type=>{const list=periods(state.goal,type);const current=currentPeriod(state.goal,type);return `<div class="reflection-type">${icon(type==='weekly'?'reflect':type==='monthly'?'calendar':'flag')}<h3>${typeName(type)} reflection</h3><p>${{weekly:'Notice your wins, the friction, and one useful adjustment.',monthly:'Step back to see patterns and the progress that matters.',end:'Compare your result with your goal and carry the lessons forward.'}[type]}</p><label class="skip-link" for="period-${type}">${typeName(type)} reflection period</label><select id="period-${type}" aria-label="${typeName(type)} reflection period">${list.map(p=>`<option value="${esc(p.key)}" ${p.key===current.key?'selected':''}>${type==='end'?`Full goal · ${prettyDate(p.end)}`:p.label}${p.due?' · due':''}${state.reflections.some(r=>r.periodKey===p.key)?' · saved':''}</option>`).join('')}</select><button class="button secondary" data-action="reflection" data-type="${type}">Open reflection ${icon('arrow')}</button></div>`;}).join('')}</section><div class="section-header"><h2>Your reflection journal</h2><small>${state.reflections.length} ${state.reflections.length===1?'entry':'entries'}</small></div><section aria-label="Saved reflections">${state.reflections.length?[...state.reflections].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(r=>`<article class="history-item"><span class="pill">${typeName(r.type)}</span><div class="history-text"><h3>${prettyDate(r.start)} – ${prettyDate(r.end)}${r.early?' <span class="due-mark">EARLY CHECK-IN</span>':''}</h3><p>${esc(r.wins)}</p></div><span class="history-date">${r.mood}/5 · ${prettyDate(r.createdAt.slice(0,10))}</span><button class="button secondary" data-action="edit-reflection" data-id="${esc(r.id)}">Revisit</button></article>`).join(''):`<div class="card empty"><div class="empty-icon">${icon('reflect')}</div><h3>Your story starts with a small observation.</h3><p>Choose a reflection above. You can write a check-in early and update it as you go.</p></div>`}</section>`;}
function render(){const names={today:'Today',plan:'My plan',reflections:'Reflections'};$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('logo')}</div><span class="brand-text">Reflect</span><span class="ai">AI</span></div><p class="nav-label">YOUR WORKSPACE</p><nav class="nav" aria-label="Workspace">${[['today','sun','Today'],['plan','plan','My plan'],['reflections','reflect','Reflections']].map(([name,ic,label])=>`<button class="${view===name?'active':''}" data-action="nav" data-view="${name}" aria-label="${label}" ${view===name?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}<p>Progress has a pace.<br>Find yours.</p></div><div class="private-note">${icon('lock')}Your personal space</div></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand"><span class="brand-mark">${icon('logo')}</span>Reflect <small style="font-size:10px;color:#8c9b7e">AI</small></div><div class="breadcrumbs"><span>My workspace</span><span style="color:#c4ccbc">/</span><span>${names[view]}</span></div><div class="top-actions"><span class="private-pill">${icon('lock')}Private workspace</span><button class="icon-button" data-action="settings" aria-label="Workspace settings and backups" title="Settings and backups">${icon('more')}</button><div class="avatar" ${account?`role="img" aria-label="Signed in as ${esc(account.email)}"`:'aria-hidden="true"'}>${icon(account?'check':'leaf')}</div></div></header><main class="main-content" id="main">${syncNotice()}${storageError?'<div class="storage-error" role="alert">Browser storage is unavailable or a saved backup could not be read. Changes may only last this session. Use Settings to export a backup.</div>':''}${view==='today'?todayView():view==='plan'?planView():reflectionsView()}<footer class="bottom-note"><span>${icon('lock')}${sync?cloudStatus==='saved'?'Saved to your account':cloudStatus==='saving'||cloudStatus==='pending'?'Saving to your account…':'Cloud save pending':state.mode==='demo'?'Example workspace':'Saved in this browser'} · Export a backup from settings</span><span>A little reflection. A little action.</span></footer></main></div></div>`;}
function modal(title,subtitle,body){lastFocus=document.activeElement;const d=$('#modal');d.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();d.scrollTop=0;}
function closeModal(){const d=$('#modal');d.close();dialogType=null;if(lastFocus?.isConnected)lastFocus.focus();}
const field=(id,label,value='',type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const textarea=(id,label,value='',extra='')=>`<div class="field"><label for="${id}">${label}</label><textarea id="${id}" name="${id}" ${extra}>${esc(value)}</textarea></div>`;
function newGoal(){dialogType='wizard';wizardStep=1;preview=null;draft={goal:{id:uid(),title:'',success:'',why:'',category:'build',startDate:today(),endDate:addDays(today(),27),dailyMinutes:30,days:[1,2,3,4,5]},checkpoints:[],actionMinutes:30};showWizard();}
function error(message){const e=$('#form-error');if(e){e.textContent=message;e.setAttribute('role','alert');e.scrollIntoView({block:'nearest'});}else notify(message);}
function readGoal(){const g=draft.goal;for(const key of ['title','success','why','category','startDate','endDate'])g[key]=$(`#goal-${key}`).value.trim();g.dailyMinutes=Number($('#goal-dailyMinutes').value);g.days=[...document.querySelectorAll('[name="workday"]:checked')].map(e=>Number(e.value));return g;}
function readCheckpoints(){draft.checkpoints=[...document.querySelectorAll('.checkpoint-editor')].map(e=>({id:e.dataset.id,title:e.querySelector('[name="checkpoint-title"]').value,deliverable:e.querySelector('[name="checkpoint-deliverable"]').value,actions:e.querySelector('[name="checkpoint-actions"]').value}));draft.actionMinutes=Number($('#action-minutes').value);}
function showWizard(){const g=draft.goal;const steps=['Name the goal','Shape the steps','Make it yours'];let body=`<p class="wizard-caption">${wizardStep} of 3 · ${steps[wizardStep-1]}</p><div class="wizard-progress" aria-hidden="true">${steps.map((_,i)=>`<span class="${i<wizardStep?'current':''}"></span>`).join('')}</div>`;
  if(wizardStep===1)body+=`<form id="goal-form">${field('goal-title','What do you want to achieve?',g.title,'text','required maxlength="180" placeholder="e.g. Launch a useful AI automation demo"')}${textarea('goal-success','What will a successful result look like?',g.success,'required maxlength="800" placeholder="e.g. A working demo tested by 3 people, with feedback recorded."')}${textarea('goal-why','Why does this matter to you? <span class="optional">Optional</span>',g.why,'maxlength="800" placeholder="A reason worth coming back to on the difficult days."')}<div class="field"><label for="goal-category">What kind of goal is this?</label><select id="goal-category">${[['build','Build or launch something'],['career','Career and clients'],['learn','Learn a skill'],['wellbeing','Build a personal routine'],['custom','Something else']].map(([v,l])=>`<option value="${v}" ${v===g.category?'selected':''}>${l}</option>`).join('')}</select></div><div class="field-grid">${field('goal-startDate','Start date',g.startDate,'date',`required min="${today()}"`)}${field('goal-endDate','Deadline',g.endDate,'date',`required min="${g.startDate}"`)}</div>${field('goal-dailyMinutes','Minutes available per workday',g.dailyMinutes,'number','required min="10" max="240" step="5"')}<div class="field"><span class="field-label" id="days-label">Which days can you make time?</span><div class="day-options" role="group" aria-labelledby="days-label">${[[1,'Mon'],[2,'Tue'],[3,'Wed'],[4,'Thu'],[5,'Fri'],[6,'Sat'],[0,'Sun']].map(([v,l])=>`<label class="day-option"><input type="checkbox" name="workday" value="${v}" ${g.days.includes(v)?'checked':''}>${l}</label>`).join('')}</div><small>Start small. The outline will stay within this time budget.</small></div><div id="form-error" class="form-error"></div><div class="modal-footer"><button type="button" class="text-button" data-action="close">Cancel</button><button type="submit" class="button">Shape my plan ${icon('arrow')}</button></div></form>`;
  if(wizardStep===2)body+=`<form id="outline-form"><div class="info-box">Suggested checkpoints give you a starting point. Edit the deliverables and actions to match <strong>${esc(g.title)}</strong>. Put one action on each line.</div>${field('action-minutes','Estimated minutes per action',draft.actionMinutes,'number',`required min="5" max="${g.dailyMinutes}" step="5"`)}<div id="checkpoint-editors">${draft.checkpoints.map((c,i)=>`<div class="checkpoint-editor" data-id="${esc(c.id)}"><div class="checkpoint-editor-head"><span>CHECKPOINT ${i+1}</span>${draft.checkpoints.length>1?`<button type="button" class="icon-button" data-action="remove-checkpoint" data-id="${esc(c.id)}" aria-label="Remove checkpoint ${i+1}">${icon('close')}</button>`:''}</div><div class="field"><label for="cp-title-${i}">Checkpoint name</label><input id="cp-title-${i}" name="checkpoint-title" value="${esc(c.title)}" required maxlength="160"></div><div class="field"><label for="cp-result-${i}">Deliverable <span class="optional">Optional</span></label><input id="cp-result-${i}" name="checkpoint-deliverable" value="${esc(c.deliverable)}" maxlength="300"></div><div class="field"><label for="cp-actions-${i}">Concrete actions, one per line</label><textarea id="cp-actions-${i}" name="checkpoint-actions" required maxlength="12000">${esc(c.actions)}</textarea></div></div>`).join('')}</div><button type="button" class="text-button" data-action="add-checkpoint">${icon('plus')} Add a checkpoint</button><div id="form-error" class="form-error"></div><div class="modal-footer"><button type="button" class="text-button" data-action="wizard-back">${icon('back')} Back</button><button type="submit" class="button">Preview schedule ${icon('arrow')}</button></div></form>`;
  if(wizardStep===3)body+=`<div class="preview-note">${icon('check')} ${preview.tasks.length} actions across ${new Set(preview.tasks.map(t=>t.date)).size} workdays, within your ${g.dailyMinutes}-minute daily budget.</div>${preview.milestones.map(m=>`<div class="preview-stage"><h3>${esc(m.title)}<span>By ${prettyDate(m.date)}</span></h3>${preview.tasks.filter(t=>t.milestoneId===m.id).map(t=>`<div class="preview-task"><span>${esc(t.title)}</span><span>${prettyDate(t.date)} · ${t.minutes}m</span></div>`).join('')}</div>`).join('')}<p class="preview-helper">You can edit any action, duration, or date in My plan. ${state.mode==='personal'?'Your current goal will be kept in Previous goals when you activate this one.':'The example will be replaced with your own goal.'}</p><div class="modal-footer"><button class="text-button" data-action="wizard-back">${icon('back')} Edit outline</button><button class="button" data-action="activate-goal">Activate my goal ${icon('arrow')}</button></div>`;
  modal(wizardStep===1?'Start with something that matters.':wizardStep===2?'Give your goal a practical path.':'Your next chapter has a plan.',wizardStep===1?'One meaningful goal. A realistic deadline. Small actions you can follow through on.':wizardStep===2?'A useful plan is specific, small, and adjustable.':'Take a look at the schedule before you make it your own.',body);
}
function activateGoal(){const archives=[...(state.archives||[])];if(state.mode==='personal'){const {archives:ignored,...previous}=state;archives.push(previous);}state={version:1,mode:'personal',goal:{...draft.goal},tasks:preview.tasks,milestones:preview.milestones,reflections:[],archives,createdAt:new Date().toISOString()};view='today';timer={remaining:1500,running:false,until:null};closeModal();saved('Your goal is ready. Start with one small step.');}
function openTask(id,reschedule=false){const t=id?state.tasks.find(t=>t.id===id):null;if(id&&!t)return;dialogType='task';const date=t?.date|| (today()<state.goal.startDate?state.goal.startDate:today()>state.goal.endDate?state.goal.endDate:today());modal(reschedule?'Make room for this action.':t?'Make this step work for you.':'A small next step.',reschedule?'Choose a date within your goal. The rest of your plan stays intact.':'Specific actions are easier to start. Give this one a clear result.',`<form id="task-form" data-id="${esc(id||'')}">${textarea('task-title','Action',t?.title||'','required maxlength="800" placeholder="e.g. Test the demo with three real examples"')}<div class="field-grid">${field('task-date','Scheduled date',date,'date',`required min="${state.goal.startDate}" max="${state.goal.endDate}"`)}${field('task-minutes','Estimated minutes',t?.minutes||Math.min(30,state.goal.dailyMinutes),'number','required min="5" max="240" step="5"')}</div><div class="field"><label for="task-milestone">Checkpoint</label><select id="task-milestone">${state.milestones.map(m=>`<option value="${esc(m.id)}" ${m.id===t?.milestoneId?'selected':''}>${esc(m.title)}</option>`).join('')}</select><small>Use a date and duration that fit your ${state.goal.dailyMinutes}-minute budget. Overloaded days will be highlighted in My plan.</small></div><div id="form-error" class="form-error"></div><div class="modal-footer">${t?`<button type="button" class="delete-link" data-action="delete-task" data-id="${esc(t.id)}">Remove action</button>`:'<button type="button" class="text-button" data-action="close">Cancel</button>'}<button type="submit" class="button">${t?'Save changes':'Add action'} ${icon('check')}</button></div></form>`);if(reschedule)$('#task-date').focus();}
function editMilestone(id){const m=milestoneFor(id);if(!m)return;dialogType='milestone';modal('A checkpoint worth reaching.','Describe a result you can recognize, rather than a vague activity.',`<form id="milestone-form" data-id="${esc(id)}">${field('milestone-title','Checkpoint name',m.title,'text','required maxlength="160"')}${textarea('milestone-deliverable','What will be ready?',m.deliverable,'maxlength="800"')}${field('milestone-date','Target date',m.date,'date',`required min="${state.goal.startDate}" max="${state.goal.endDate}"`)}<div id="form-error" class="form-error"></div><div class="modal-footer"><button type="button" class="text-button" data-action="close">Cancel</button><button type="submit" class="button">Save checkpoint</button></div></form>`);}
function openReflection(type,periodKey,id){if(!['weekly','monthly','end'].includes(type))return;const entry=id?state.reflections.find(r=>r.id===id):null;const key=entry?.periodKey||periodKey||$(`#period-${type}`)?.value;const p=periods(state.goal,type).find(p=>p.key===key)||currentPeriod(state.goal,type);const r=entry||state.reflections.find(r=>r.periodKey===p.key);const completed=state.tasks.filter(t=>t.done&&t.completedOn>=p.start&&t.completedOn<=p.end).length;const planned=state.tasks.filter(t=>t.date>=p.start&&t.date<=p.end).length;const canAdd=today()<=state.goal.endDate;dialogType='reflection';modal(`${typeName(type)} reflection.`,`${prettyDate(p.start,{month:'short',day:'numeric',year:'numeric'})} – ${prettyDate(p.end,{month:'short',day:'numeric',year:'numeric'})}`,`<form id="reflection-form" data-type="${type}" data-period="${esc(p.key)}"><div class="reflection-context">${completed} actions completed during this period · ${planned} actions scheduled.${!p.due?`<br>This is an early check-in. Your period ends ${prettyDate(p.end)}; you can revisit this reflection later.`:''}${type==='end'?`<br>Your success measure: ${esc(state.goal.success)}`:''}</div><div class="field"><span class="field-label" id="mood-label">How are you feeling about your progress?</span><div class="mood-options" role="radiogroup" aria-labelledby="mood-label">${['Stuck','Uneven','Steady','Good','Great'].map((label,i)=>`<label class="mood-option"><input type="radio" name="mood" value="${i+1}" ${(r?.mood||3)===i+1?'checked':''}><strong>${i+1}</strong><span>${label}</span></label>`).join('')}</div></div>${textarea('reflection-wins',type==='end'?'What did you achieve, compared with your goal?':'What moved forward?',r?.wins||'','required maxlength="4000" placeholder="Small wins count. Be specific about what changed."')}${textarea('reflection-challenges','What got in the way? <span class="optional">Optional</span>',r?.challenges||'','maxlength="4000" placeholder="Time, energy, unclear steps, unexpected friction..."')}${textarea('reflection-lesson','What will you carry forward? <span class="optional">Optional</span>',r?.lesson||'','maxlength="4000" placeholder="One useful lesson or adjustment."')}${textarea('reflection-next','One concrete next step <span class="optional">Optional</span>',r?.next||'','maxlength="800" placeholder="An action you can actually put on the calendar."')}${canAdd?`<label class="checkbox-label"><input type="checkbox" id="reflection-add" ${r?.nextTaskId?'':'checked'}> ${r?.nextTaskId?'Update the linked action with this next step':'Add this next step to my plan'}</label><div class="field-grid" id="next-step-fields">${field('reflection-date','Next step date',state.tasks.find(t=>t.id===r?.nextTaskId)?.date||(today()<state.goal.startDate?state.goal.startDate:today()),'date',`min="${state.goal.startDate}" max="${state.goal.endDate}"`)}${field('reflection-minutes','Minutes',state.tasks.find(t=>t.id===r?.nextTaskId)?.minutes||Math.min(30,state.goal.dailyMinutes),'number','min="5" max="240" step="5"')}</div>`:'<p class="preview-helper">This goal’s deadline has passed. Capture your next step here, then create your next goal when you’re ready.</p>'}<div id="form-error" class="form-error"></div><div class="modal-footer"><button type="button" class="text-button" data-action="close">Cancel</button><button type="submit" class="button">Save reflection ${icon('check')}</button></div></form>`);if(canAdd&&r?.nextTaskId)$('#next-step-fields').classList.add('hidden');}
function settings(){dialogType='settings';modal('Your workspace, your record.','Keep a backup of your goal, actions, and reflections.',`${account?`<div class="info-box"><p>Signed in as <strong>${esc(account.email)}</strong>.</p><form method="post" action="/auth/logout"><button type="submit" class="button secondary">Sign out</button></form></div>`:''}<div class="info-box"><p>${sync?'Your plans and reflections are saved to your private account and can be opened on another device. A local backup helps preserve unsaved changes.':'This is a local preview. Your planning data is stored in this browser on this device.'}</p><p>The planner uses editable goal templates and schedules them around your available time. It does not send your goal to an AI service.</p><p>Check that changes are saved to your account before closing the page. Export a backup before clearing site data. Imported backups replace the current workspace after confirmation.</p></div><div class="settings-list">${recovered?`<div class="settings-row"><div><h3>Earlier unsaved version</h3><p>Download this preserved backup before choosing what to restore.</p></div><button class="button secondary" data-action="export-recovery">Download backup</button></div>`:''}<div class="settings-row"><div><h3>Export my workspace</h3><p>Download a JSON backup, including previous goals.</p></div><button class="button secondary" data-action="export">${icon('download')} Export</button></div><div class="settings-row"><div><h3>Restore a backup</h3><p>Bring back a workspace exported from Reflect AI.</p></div><button class="button secondary" data-action="import">${icon('upload')} Import</button></div><div class="settings-row"><div><h3>Previous goals</h3><p>${state.archives.length} saved ${state.archives.length===1?'goal':'goals'}. Only one goal is active at a time.</p></div><button class="button secondary" data-action="archives">${icon('archive')} Open</button></div><div class="settings-row"><div><h3>${state.mode==='demo'?'Make it your own':'Start another goal'}</h3><p>${state.mode==='demo'?'Replace the example with a goal that matters to you.':'Your current goal will be kept in Previous goals.'}</p></div><button class="button" data-action="new-goal">${icon('plus')} Create goal</button></div></div>`);}
function exportBackup(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download=`reflect-ai-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Your workspace backup has been downloaded.');}
function archives(){dialogType='archives';modal('The chapters you’ve worked on.','Opening a previous goal keeps your current goal here.',state.archives.length?state.archives.map((a,i)=>`<div class="archive-item"><div><h3>${esc(a.goal.title)}</h3><p>${prettyDate(a.goal.startDate)} – ${prettyDate(a.goal.endDate)} · ${a.reflections.length} reflections</p></div><button class="button secondary" data-action="restore-goal" data-index="${i}">Open goal</button></div>`).join(''):'<div class="empty"><div class="empty-icon">'+icon('archive')+'</div><h3>One chapter at a time.</h3><p>Your goals will appear here when you start your next one.</p></div>');}
function timerText(){const n=Math.max(0,timer.remaining);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function updateTimer(){if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.until-Date.now())/1000));if(timer.remaining===0){timer.running=false;timer.until=null;notify('Focus session complete. Take a breath and notice your progress.');}}if($('#timer-display')){$('#timer-display').textContent=timerText();$('#timer-button').innerHTML=icon(timer.running?'pause':'play')+(timer.running?'Pause':'Start focus');$('#timer-caption').textContent=timer.remaining===0?'A good moment for a break':timer.running?'One action. A little attention.':'A little space to focus';}}
setInterval(updateTimer,1000);
let lastDay=today();document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateTimer();if(lastDay!==today()){lastDay=today();render();}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;
  switch(action){
    case 'nav':view=b.dataset.view;render();window.scrollTo({top:0});break;
    case 'close':closeModal();break;
    case 'new-goal':newGoal();break;
    case 'toggle':{const t=state.tasks.find(t=>t.id===id);if(!t)break;t.done=!t.done;t.completedOn=t.done?today():null;const completed=t.done;saved(completed?'One small step forward. Nicely done.':'Action marked incomplete.');const check=[...document.querySelectorAll('[data-action="toggle"]')].find(el=>el.dataset.id===id);check?.focus();break;}
    case 'add-task':openTask();break;
    case 'edit-task':openTask(id);break;
    case 'reschedule':openTask(id,true);break;
    case 'delete-task':{const t=state.tasks.find(t=>t.id===id);if(!t)break;dialogType='confirm-delete';modal('Remove this action?',esc(t.title),`<p class="preview-helper">This removes the action from the plan and progress totals.</p><div class="modal-footer"><button class="text-button" data-action="edit-task" data-id="${esc(id)}">Keep action</button><button class="button danger" data-action="confirm-delete" data-id="${esc(id)}">Remove action</button></div>`);break;}
    case 'confirm-delete':state.tasks=state.tasks.filter(t=>t.id!==id);closeModal();saved('Action removed from your plan.');break;
    case 'edit-milestone':editMilestone(id);break;
    case 'wizard-back':if(wizardStep===2)readCheckpoints();wizardStep--;showWizard();break;
    case 'remove-checkpoint':readCheckpoints();draft.checkpoints=draft.checkpoints.filter(c=>c.id!==id);showWizard();break;
    case 'add-checkpoint':readCheckpoints();if(draft.checkpoints.length>=8){error('Keep this first plan to eight checkpoints or fewer.');break;}draft.checkpoints.push({id:uid(),title:'',deliverable:'',actions:''});showWizard();break;
    case 'activate-goal':activateGoal();break;
    case 'reflection':openReflection(b.dataset.type,b.dataset.period);break;
    case 'edit-reflection':{const r=state.reflections.find(r=>r.id===id);if(r)openReflection(r.type,r.periodKey,id);break;}
    case 'settings':settings();break;
    case 'export':exportBackup();break;
    case 'sync-retry':sync?.retry();break;
    case 'export-recovery':{if(!recovered)break;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(recovered,null,2)],{type:'application/json'}));a.download='reflect-ai-unsaved-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);break;}
    case 'import':$('#import-file').click();break;
    case 'confirm-import':state=window.pendingImport;delete window.pendingImport;view='today';timer={remaining:1500,running:false,until:null};closeModal();saved('Your workspace has been restored.');break;
    case 'archives':archives();break;
    case 'restore-goal':{const index=Number(b.dataset.index),a=state.archives[index];if(!a)break;const list=state.archives.filter((_,i)=>i!==index);if(state.mode==='personal'){const {archives:ignored,...prev}=state;list.push(prev);}state={...a,archives:list};view='today';closeModal();saved('Previous goal opened.');break;}
    case 'timer':if(timer.running){updateTimer();timer.running=false;timer.until=null;}else{if(timer.remaining===0)timer.remaining=1500;timer.running=true;timer.until=Date.now()+timer.remaining*1000;}updateTimer();break;
    case 'timer-reset':timer={remaining:1500,running:false,until:null};updateTimer();break;
  }
});
document.addEventListener('submit',e=>{if(!e.target.matches('#goal-form,#outline-form,#task-form,#reflection-form,#milestone-form'))return;e.preventDefault();
  if(e.target.id==='goal-form'){const oldCategory=draft.goal.category,oldTitle=draft.goal.title,oldSuccess=draft.goal.success;const g=readGoal(),issue=validateGoal(g);if(issue){error(issue);return;}if(!draft.checkpoints.length||g.category!==oldCategory||g.title!==oldTitle||g.success!==oldSuccess){draft.checkpoints=suggestCheckpoints(g.category,g.title,g.success);draft.actionMinutes=Math.min(g.dailyMinutes,30);}wizardStep=2;showWizard();}
  if(e.target.id==='outline-form'){readCheckpoints();try{preview=generatePlan(draft.goal,draft.checkpoints,draft.actionMinutes);wizardStep=3;showWizard();}catch(err){error(err.message);}}
  if(e.target.id==='task-form'){const id=e.target.dataset.id,title=$('#task-title').value.trim(),date=$('#task-date').value,minutes=Number($('#task-minutes').value),milestoneId=$('#task-milestone').value;if(!title){error('Write a specific action.');return;}if(!isDate(date)||date<state.goal.startDate||date>state.goal.endDate){error('Schedule this action within the goal’s dates.');return;}if(!Number.isInteger(minutes)||minutes<5||minutes>240){error('Choose an estimate between 5 and 240 minutes.');return;}const t=state.tasks.find(t=>t.id===id);if(t)Object.assign(t,{title,date,minutes,milestoneId});else state.tasks.push({id:uid(),title,date,minutes,milestoneId,done:false,completedOn:null});const m=milestoneFor(milestoneId);if(m&&date>m.date)m.date=date;closeModal();saved(t?'Your action has been updated.':'A small next step, added to your plan.');}
  if(e.target.id==='milestone-form'){const m=milestoneFor(e.target.dataset.id),title=$('#milestone-title').value.trim(),date=$('#milestone-date').value;if(!title||!isDate(date)||date<state.goal.startDate||date>state.goal.endDate){error('Choose a name and a date within your goal.');return;}const last=state.tasks.filter(t=>t.milestoneId===m.id).sort((a,b)=>b.date.localeCompare(a.date))[0];if(last&&date<last.date){error(`This checkpoint has an action on ${prettyDate(last.date)}. Move that action first or use a later target date.`);return;}Object.assign(m,{title,deliverable:$('#milestone-deliverable').value.trim(),date});closeModal();saved('Checkpoint updated.');}
  if(e.target.id==='reflection-form'){const type=e.target.dataset.type,p=periods(state.goal,type).find(p=>p.key===e.target.dataset.period);if(!p)return;const wins=$('#reflection-wins').value.trim(),challenges=$('#reflection-challenges').value.trim(),lesson=$('#reflection-lesson').value.trim(),next=$('#reflection-next').value.trim();if(!wins){error('Capture at least one observation about your progress.');return;}const existing=state.reflections.find(r=>r.periodKey===p.key),add=!!$('#reflection-add')?.checked;let nextTaskId=existing?.nextTaskId||null;if(add&&next){const date=$('#reflection-date').value,minutes=Number($('#reflection-minutes').value);if(!isDate(date)||date<state.goal.startDate||date>state.goal.endDate){error('Choose a next step date within your goal.');return;}if(!Number.isInteger(minutes)||minutes<5||minutes>240){error('Choose a next step estimate between 5 and 240 minutes.');return;}let t=state.tasks.find(t=>t.id===nextTaskId);if(t)Object.assign(t,{title:next,date,minutes});else{const m=state.milestones.find(m=>m.date>=date)||state.milestones.at(-1);t={id:uid(),title:next,date,minutes,milestoneId:m.id,done:false,completedOn:null};state.tasks.push(t);nextTaskId=t.id;}const m=milestoneFor(t.milestoneId);if(m&&date>m.date)m.date=date;}const data={id:existing?.id||uid(),type,periodKey:p.key,start:p.start,end:p.end,wins,challenges,lesson,next,mood:Number(document.querySelector('[name="mood"]:checked').value),createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),early:!p.due,nextTaskId};if(existing)Object.assign(existing,data);else state.reflections.push(data);closeModal();saved(add&&next?'Reflection saved, with a next step in your plan.':'A little perspective, saved for later.');}
});
document.addEventListener('change',e=>{if(e.target.id==='goal-startDate')$('#goal-endDate').min=e.target.value;if(e.target.id==='reflection-add')$('#next-step-fields').classList.toggle('hidden',!e.target.checked);});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){notify('That backup is too large. Choose a Reflect AI JSON backup under 5 MB.');return;}try{const data=JSON.parse(await file.text());if(!validateImport(data))throw new Error('Invalid backup');window.pendingImport=data;dialogType='confirm-import';modal('Restore this workspace?',esc(data.goal.title),`<div class="info-box">This backup contains ${data.tasks.length} actions, ${data.reflections.length} reflections, and ${data.archives.length} previous goals. It will replace your current workspace and sync to your account when connected.</div><p class="preview-helper">Export the current workspace first if you want to keep it.</p><div class="button-group"><button class="button secondary" data-action="export">${icon('download')} Export current workspace</button></div><div class="modal-footer"><button class="text-button" data-action="settings">Cancel</button><button class="button" data-action="confirm-import">Restore backup</button></div>`);}catch{notify('This file is not a valid Reflect AI backup. Your workspace has not changed.');}});
$('#modal').addEventListener('cancel',()=>{dialogType=null;});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
if(resumePending&&sync){persist();sync.enqueue(state);}
